import{_ as a,o,c as s}from"./chunks/framework.D1Ss-Xl7.js";const m=JSON.parse('{"title":"modal Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"modal","tag":"modal","title":"modal Tag","prev":null,"next":null,"posts":[{"title":"网站开发中的Modal问题","url":"/posts/2017-10-21-modal-scroll/","date":"2017-10-21 14:30","tags":["web","modal"],"html":"<p>最近在开发的网站基本上全是使用弹出的对话框（Modal）来进行 UI 交互的，所以对于 Modal 的处理也算积攒了一点经验。便想写下来供自己以后参考和学习。说实话，在目前响应式布局的主流开发方式下，Modal 非常不适合作为一个良好的交互方式。因为对于手机触屏用户非常不友好。当然，我开发的这个网站也没有考虑手机用户。当前的主流方式还是采用 SPA，JS 软路由切换页面来交互才是正解。</p>\\n<h2 id=\\"modal-元素的位置\\" tabindex=\\"-1\\">Modal 元素的位置 <a class=\\"header-anchor\\" href=\\"#modal-元素的位置\\" aria-label=\\"Permalink to &quot;Modal 元素的位置&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>弹出对话框的方式基本是把对话框的<code>z-index</code>设置的比当前页面元素高，然后使用<code>opacity: 0.5</code>来半透明进行遮罩。但是，需要使用 Modal 的内容最好放在 body 的下层，而不是嵌套了好多层的某个 div 里面，因为子元素的<code>z-index</code>是不可能大于父元素的，会导致在某些情况下，其他元素比当前的 Modal<code>z-index</code>更高。</p>\\n<h2 id=\\"modal-滚动条问题\\" tabindex=\\"-1\\">Modal 滚动条问题 <a class=\\"header-anchor\\" href=\\"#modal-滚动条问题\\" aria-label=\\"Permalink to &quot;Modal 滚动条问题&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>很多情况下，弹出的 Modal 内容过多导致会产生滚动条。这时如果不处理好会导致出现双重滚动条。一条是页面本身的内容过多产生的滚动条，还有一条是 Modal 自身的。双重滚动条还有一个问题是当你在 Modal 里面进行滚动的时候，页面内容本身也会被滚动，这会导致关闭 Modal 的时候发现页面的位置已不是打开的位置了，用户体验非常不好。这时候有两种解决方案。</p>\\n<p>第一个方案是页面本身采用<code>position:fixed</code>进行固定，并用 JS 记住滚动位置，但必须保持页面本身和 Modal 是并列关系。例：</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">body</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#6F42C1\\"> class</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"content\\"</span><span style=\\"color:#24292E\\">>&#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#6F42C1\\"> class</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"modal\\"</span><span style=\\"color:#24292E\\">>&#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#22863A\\">body</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>这样，Modal 采用<code>position:absolute</code>定位，当内容过长就会自动出现滚动条。但是当关闭 Modal 的时候，必须把网页内容的<code>position:fixed</code>属性去除，并用 JS 滚动到当初打开 Modal 的位置。如果 Modal 是透明的，那就必须在打开 Modal 的时候设置网页内容的<code>top</code>和<code>left</code>属性来保持位置不变。</p>\\n<p>第二个方案是，网页内容采用<code>overflow: hidden</code>来隐藏滚动条。Modal 采用<code>position：fixed</code>方案进行定位，但是这时候 Modal 不得不设置<code>overflow： auto</code>来进行滚动。\\n第二个方案对于网页内容和 Modal 的位置并没有特殊的要求，比较灵活，而且不需要 JS 的介入。</p>\\n<h2 id=\\"浏览器重绘\\" tabindex=\\"-1\\">浏览器重绘 <a class=\\"header-anchor\\" href=\\"#浏览器重绘\\" aria-label=\\"Permalink to &quot;浏览器重绘&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>在一个方案中，由于网页内容被设置成了<code>position:fixed</code>，滚动条自然消失。所以滚动位置回到了浏览器的最上面才对。但是有时候遇到打开<code>Modal</code>的时候发现 Modal 打开之后滚动条不在最上方，这时候的原因是因为我们虽然设置了 CSS 进行了变更，但是浏览器没有进行重新绘制，我们可以使用会导致浏览器重绘的 JS API 来让浏览器更新滚动条信息，使得打开的 Modal 处于浏览器的最上方。</p>\\n<p>参考：</p>\\n<p><a href=\\"https://gist.github.com/paulirish/5d52fb081b3570c81e3a\\" target=\\"_blank\\" rel=\\"noreferrer\\">Force reflow</a></p>\\n"}]},"relativePath":"tags/modal/index.md","filePath":"tags/[slug].md"}'),e={name:"tags/modal/index.md"};function l(n,d,p,t,c,r){return o(),s("div")}const h=a(e,[["render",l]]);export{m as __pageData,h as default};
